def specified_element(m, idx):
    """The program dawnr proved in `t`, written in Python (checked against `t`, not itself proved).

    requires idx >= 0
    requires forall i in [0, len(m)) . idx < len(m[i])
    ensures  len(r) == len(m)
    ensures  forall i in [0, len(m)) . r[i] == m[i][idx]

    Outside its `requires` it raises ValueError: nothing was proved there.
    """
    if not (_t_ints(m, 2)):
        raise TypeError('specified_element: `m` must be a list of lists of integers; nothing was proved for anything else')
    if not (_t_ints(idx, 0)):
        raise TypeError('specified_element: `idx` must be an integer; nothing was proved for anything else')
    m = _t_tuple(m)
    if not _t_requires(m, idx):
        raise ValueError('specified_element: this input is outside what was proved (requires idx >= 0; forall i in [0, len(m)) . idx < len(m[i]))')
    _t_result = _t_core(m, idx)
    return _t_list(_t_result)

def _t_core(m, idx):
    r = ()
    i = 0
    # invariant: 0 <= i
    # invariant: i <= len(m)
    # invariant: len(r) == i
    # invariant: forall j in [0, i) . r[j] == m[j][idx]
    # decreases: len(m) - i
    while (i < len(m)):
        r = (r + (m[i][idx], ))
        i = (i + 1)
    return r

def _t_requires(m, idx):
    try:
        return bool((idx >= 0)) and bool(all((idx < len(m[i])) for i in range(0, len(m))))
    except (IndexError, ZeroDivisionError):   # a `requires` with no value here admits nothing
        return False

def _t_tuple(v):
    return tuple(_t_tuple(x) for x in v) if isinstance(v, (list, tuple)) else v

def _t_ints(v, depth):
    if depth == 0:
        return isinstance(v, int) and not isinstance(v, bool)
    return isinstance(v, (list, tuple)) and all(_t_ints(x, depth - 1) for x in v)

def _t_list(v):
    return [_t_list(x) for x in v] if isinstance(v, tuple) else v

